  "영상 파이프라인": "影像管线",
  "WASM 디코딩 파이프라인 (베타) — 원본 픽셀(WADO-RS bulkdata)을 브라우저에서 직접 디코딩": "WASM 解码管线（Beta）— 在浏览器直接解码原始像素 (WADO-RS bulkdata)",
  "켜면 2D 뷰어가 서버 렌더링(JPEG) 대신 원본 16bit 프레임을 받아 WASM 코덱으로 디코딩합니다. W/L 조정이 서버 왕복 없이 즉시 반영되고, 병원 설정의 전송구문(JPEG2000/JPEG-LS)으로 수신합니다. 디코딩 전에는 서버 렌더링으로 표시(자동 폴백).": "开启后 2D 查看器不用服务器渲染 (JPEG)，而是接收原始 16bit 帧并用 WASM 编解码器解码。W/L 调整无需服务器往返即时反映，按医院设置的传输语法 (JPEG2000/JPEG-LS) 接收。解码前以服务器渲染显示（自动回退）。",
  "제품 모드 프로파일 (05 Mode Profile — 서버 JSON)": "产品模式配置 (05 Mode Profile — 服务器 JSON)",
