  "판독 도크 History의 과거검사(Prior Studies) 썸네일 클릭 시 적용. Monitor 띄우기 예: 모니터 1·2·3에서 3번 기준→2번, 1번 기준→2번에 표시. 조건 미충족(단일 모니터·감지/팝업 차단) 시 Layout 1:2로 폴백. ⇄ Compare(다중 선택)의 다중 모니터 배치는 위 체크가 담당합니다. 창 관리 권한(HTTPS)·팝업 허용 필요.": "点击报告停靠栏 History 的既往检查 (Prior Studies) 缩略图时应用。Monitor 打开示例：显示器 1·2·3 中以 3 号为基准→2 号，以 1 号为基准→2 号显示。条件不满足（单显示器·检测/弹窗被拦）时回退到 Layout 1:2。⇄ Compare（多选）的多显示器布局由上面的勾选负责。需要窗口管理权限 (HTTPS)·允许弹窗。",
