  "화면 조작(줌·팬·W/L)은 발표자 1명만 전원에게 송출합니다. 나머지 참가자는 각자 자유롭게 보며, 주석·커서는 항상 전원에게 공유됩니다.": "仅主讲人向全体广播画面操作（缩放/平移/窗宽窗位）。其他人可自由浏览；标注与光标始终共享给所有人。",
  "참여자 표시": "参与者显示",
  "마우스 커서 옆에 참여자 아이디 표시": "在鼠标光标旁显示参与者 ID",
  "참여자별 색으로 커서·툴·글자 구분": "以参与者颜色区分光标、工具与文字",
  "화상·음성 네트워크 (STUN/TURN)": "音视频网络（STUN/TURN）",
  "병원 내부망은 비워 두면 됩니다. 인터넷을 건너는 협진에만 STUN/TURN 을 넣으세요 (JSON 배열).": "院内网络请留空。仅跨互联网协同阅片时填写 STUN/TURN（JSON 数组）。",
  "계측·주석 그리기 (세션 한정 — 판독에는 Master 채택 시에만 저장)": "绘制测量与标注（仅限本次协同 — 仅 Master 采纳后才保存到报告）",
  "텍스트·글쓰기 (세션 한정)": "文字与书写（仅限本次协同）",
  "검사 탭 전환·과거 검사 열기": "切换检查标签 / 打开既往检查",
  "적용 순서(고정)": "应用顺序（固定）",
  ": ① 행잉(HP — 선택 시만) → ② Mammo(2D-MG — 선택 시만) → ③ 이 Common 표 → ④ 각 뷰어별 표 → ⑤ 자동 규칙(1×1 등).": "：① 挂片协议（HP — 仅在选中时）→ ② 乳腺（2D-MG — 仅在选中时）→ ③ 本 Common 表 → ④ 各查看器表 → ⑤ 自动规则（1×1 等）。",
  "이 표에 해당 모달리티 행이 있으면 세 뷰어(SaintView/I-View/T-View) 모두 이 값을 씁니다. 행이 없으면 그 뷰어의 개별 표를 봅니다.": "若本表中有该模态的行，三个查看器（SaintView/I-View/T-View）均使用该值；若没有，则查看该查看器自己的表。",
  "규정이 켜져 있을 때만 그 규정을 따릅니다(이 표에 MG 행이 없는 이유).": "仅在该规则开启时生效（因此本表没有 MG 行）。",
  "행은 그 표에 행이 없는 나머지 모달리티에 적용됩니다 —": "行适用于该表中没有行的其余模态 —",
  "적용 순서(고정): Common 표에 그 모달리티 행이 있으면 Common 이 우선하고, 없을 때 이 표가 적용됩니다.": "顺序（固定）：若 Common 表中有该模态的行，则 Common 优先；没有时才应用本表。",
  ")는 아래": "）遵循下方",
  "별도 창으로 크게 보기 (다른 모니터로 옮길 수 있습니다)": "在独立窗口中放大查看（可移至其他显示器）",
  "팝업이 차단되었습니다 — 이 사이트의 팝업을 허용해 주세요": "弹出窗口被拦截 — 请允许本站的弹出窗口",
