  "좌우 비율 무시": "忽略左右比例",
  "조직 탐지와 무관하게 항상 같은 고정 비율로 가운데 여백 제거 (기본 켬)": "无论组织检测结果如何，始终以相同的固定比例去除中间空隙（默认开启）",
  "자동 탐지가 영상마다 실패·지연하면 배치가 들쭉날쭉해집니다 — 켜 두면 항상 같은 모양으로 나옵니다. 해제하면 아래 흉벽 판정(자동 탐지) 규칙을 씁니다.": "当自动检测在部分图像上失败或延迟时，排版会参差不齐 — 保持开启可获得一致的显示。取消勾选则使用下方的胸壁判定（自动检测）规则。",
  "드래그 = 컬럼 위치 이동 · 오른쪽 가장자리 드래그 = 폭 조절": "拖动 = 移动列 · 拖动右边缘 = 调整宽度",
