  "표시 = 그리드 컬럼 · 검색 = 검색 필터 바 노출 · 행 드래그/▲▼ = 순서. 그리드 헤더를 드래그해 바꾼 순서와 같은 저장(계정별·뷰어별)이라 서로 그대로 반영됩니다.": "显示 = 网格列 · 搜索 = 出现在筛选栏 · 拖动行/▲▼ = 顺序。与拖动网格表头相同的保存（按账户·按查看器），双向同步。",
