  "워크리스트 '의뢰 일시' 컬럼의 표시 형식입니다.": "工作列表\"申请时间\"列的显示格式。",
  "문법: =단어(정확) · 단어%(접두) · !단어(제외) · 공백=다중어. 범위·방식·형식 모두 계정별 저장(로밍)입니다.": "语法：=词（精确）· 词%（前缀）· !词（排除）· 空格=多词。范围·方式·格式均按账户保存（漫游）。",
  "⚠ Live(원격 직결)는 원격 PACS 파라미터 한계로 환자 ID/이름에만 통합 검색이 적용됩니다.": "⚠ Live（远程直连）因远程 PACS 参数限制，统一搜索仅适用于患者 ID/姓名。",
