  "검색 방식 — SEARCH: 선택한 범위에서 문법 검색(=정확/접두%/!제외/공백=다중어) · AI: 자연어를 필터로 변환": "搜索方式 — SEARCH：在所选范围内语法搜索（=精确/前缀%/!排除/空格=多词）· AI：自然语言转筛选",
