  "기기 프로필": "设备配置档",
  "같은 계정을 최대 3개 시스템에서 동시에 사용할 수 있습니다. 모니터 구성·패널 크기 같은 장비 의존 설정은 기기(슬롯)별로 서버에 저장되고, 컬럼 구성 등 나머지 설정은 모든 기기에 공통입니다.": "同一账号最多可在 3 台系统上同时使用。显示器布局、面板大小等依赖硬件的设置按设备（槽位）分别保存在服务器上；列配置等其余设置在所有设备间共用。",
