  "이미 3개 시스템에서 이 계정으로 로그인되어 있습니다.": "该账号已在 3 台系统上登录。",
  "가장 오래 사용하지 않은 시스템을 종료하고 여기에서 로그인하시겠습니까?": "要注销最久未使用的系统并在此登录吗？",
