  "지금은 닫을 때마다 다이얼로그로 묻습니다. 다이얼로그에서 \"기본으로\"를 체크하면 그 동작이 여기에 저장됩니다.": "目前每次关闭都会弹出对话框询问。在对话框中勾选“设为默认”后，该动作会保存到这里。",
  "닫기 다이얼로그 없이 위 동작으로 바로 닫습니다. 체크를 해제하면 다시 다이얼로그가 나타납니다.": "不显示关闭对话框，直接按上述动作关闭。取消勾选后对话框会重新出现。",
